-- STRICTLY READ ONLY. Run after 202608290002 is manually applied.
with checks(check_name,status,details,blocking) as (
 values
 ('ACCOUNT_TABLES',case when to_regclass('public.tyre_shop_bills') is not null and to_regclass('public.tyre_shop_payments') is not null and to_regclass('public.tyre_shop_payment_allocations') is not null then 'PASS' else 'FAIL' end,'Tyre Shop bills, payments and allocations exist',true),
 ('ACCOUNT_RLS',case when not exists(select 1 from pg_class where oid in(to_regclass('public.tyre_shop_bills'),to_regclass('public.tyre_shop_payments'),to_regclass('public.tyre_shop_payment_allocations')) and not relrowsecurity) then 'PASS' else 'FAIL' end,'RLS enabled on all accounting tables',true),
 ('ACCOUNT_MUTATION_GUARDS',case when (select count(*) from pg_trigger where tgname in('tyre_shop_bills_protect','tyre_shop_payments_protect','tyre_shop_allocations_protect') and not tgisinternal)=3 then 'PASS' else 'FAIL' end,'All accounting tables have authoritative mutation guards',true),
 ('DIRECT_ACCOUNT_MUTATION_BLOCKED',case when not has_table_privilege('authenticated','public.tyre_shop_bills','INSERT') and not has_table_privilege('authenticated','public.tyre_shop_payments','INSERT') and not has_table_privilege('authenticated','public.tyre_shop_payment_allocations','INSERT') then 'PASS' else 'FAIL' end,'Browser direct financial writes blocked',true),
 ('PAYMENT_RPC_SIGNATURES',case when to_regprocedure('public.save_tyre_shop_payment(bigint,uuid,date,numeric,numeric,text,text,text)') is not null and to_regprocedure('public.delete_tyre_shop_payment(bigint)') is not null and to_regprocedure('public.rebuild_tyre_shop_accounting(uuid)') is not null then 'PASS' else 'FAIL' end,'Exact payment/rebuild RPC signatures',true),
 ('PAYMENT_RPC_SECURITY',case when exists(select 1 from pg_proc where oid=to_regprocedure('public.save_tyre_shop_payment(bigint,uuid,date,numeric,numeric,text,text,text)') and prosecdef and array_to_string(proconfig,',') ilike '%search_path=public, pg_temp%') and has_function_privilege('authenticated','public.save_tyre_shop_payment(bigint,uuid,date,numeric,numeric,text,text,text)','EXECUTE') and not has_function_privilege('anon','public.save_tyre_shop_payment(bigint,uuid,date,numeric,numeric,text,text,text)','EXECUTE') then 'PASS' else 'FAIL' end,'SECURITY DEFINER, locked path, authenticated only',true),
 ('FIRST_PAYMENT_ALIAS_SAFETY',case when pg_get_functiondef(to_regprocedure('public.rebuild_tyre_shop_accounting(uuid)')) ilike '%payment_row record%' and pg_get_functiondef(to_regprocedure('public.rebuild_tyre_shop_accounting(uuid)')) ilike '%bill_row record%' and pg_get_functiondef(to_regprocedure('public.rebuild_tyre_shop_accounting(uuid)')) not like '% p record%' then 'PASS' else 'FAIL' end,'Named record variables avoid the Oil first-payment alias collision',true),
 ('SOURCE_COVERAGE',case when (select count(*) from public.tyre_shop_bills)=(select count(*) from public.tyre_vehicle_entries where source_type='external_shop' and total_amount>0) then 'PASS' else 'FAIL' end,'Every eligible external-shop entry has exactly one bill',true),
 ('SOURCE_BILL_IDENTITY',case when not exists(select 1 from public.tyre_shop_bills b join public.tyre_vehicle_entries e on e.id=b.tyre_vehicle_entry_id where b.amount<>e.total_amount or b.adda_id<>e.adda_id or b.tyre_shop_id<>e.tyre_shop_id or e.source_type<>'external_shop') then 'PASS' else 'FAIL' end,'Bill references and amount match authoritative Tyre entry',true),
 ('NO_ADDA_STOCK_LIABILITY',case when not exists(select 1 from public.tyre_shop_bills b join public.tyre_vehicle_entries e on e.id=b.tyre_vehicle_entry_id where e.source_type='adda_stock') then 'PASS' else 'FAIL' end,'Adda-stock entries never create supplier liability',true),
 ('NO_DUPLICATE_SOURCE_BILLS',case when not exists(select 1 from public.tyre_shop_bills group by tyre_vehicle_entry_id having count(*)>1) then 'PASS' else 'FAIL' end,'One accounting bill per authoritative source',true),
 ('ALLOCATION_INTEGRITY',case when not exists(select 1 from public.tyre_shop_payment_allocations a left join public.tyre_shop_payments p on p.id=a.payment_id left join public.tyre_shop_bills b on b.id=a.tyre_shop_bill_id where p.id is null or b.id is null or p.tyre_shop_id<>b.tyre_shop_id or a.amount<=0) and not exists(select 1 from public.tyre_shop_payment_allocations group by payment_id,tyre_shop_bill_id having count(*)>1) then 'PASS' else 'FAIL' end,'No orphan, cross-shop or duplicate allocations',true),
 ('NO_ORPHAN_PAYMENTS',case when not exists(select 1 from public.tyre_shop_payments p left join public.tyre_shops s on s.id=p.tyre_shop_id where s.id is null or s.shop_type<>'external_supplier') then 'PASS' else 'FAIL' end,'Every payment belongs to an external Tyre Shop',true),
 ('STRICT_ADDA_ISOLATION',case when not exists(select 1 from public.tyre_shop_bills b join public.tyre_vehicle_entries e on e.id=b.tyre_vehicle_entry_id join public.tyre_shops s on s.id=b.tyre_shop_id where b.adda_id<>e.adda_id or b.adda_id<>s.adda_id) then 'PASS' else 'FAIL' end,'Bill, source and supplier Adda ownership is consistent',true),
 ('FIFO_REBUILD_CONTRACT',case when pg_get_functiondef(to_regprocedure('public.rebuild_tyre_shop_accounting(uuid)')) ilike '%order by payment_date,created_at,id%' and pg_get_functiondef(to_regprocedure('public.rebuild_tyre_shop_accounting(uuid)')) ilike '%order by bill_date,created_at,id%' then 'PASS' else 'FAIL' end,'Payments and bills are rebuilt chronologically/FIFO',true),
 ('DELETE_CASHBOOK_CLEANUP',case when pg_get_functiondef(to_regprocedure('public.delete_tyre_shop_payment(bigint)')) ilike '%delete from public.cashbook_entries%' and pg_get_functiondef(to_regprocedure('public.delete_tyre_shop_payment(bigint)')) ilike '%tyre_shop_payment%' then 'PASS' else 'FAIL' end,'Deleting a payment removes its automatic Cashbook row before rebuild',true),
 ('PAYMENT_SNAPSHOT_INVARIANTS',case when not exists(select 1 from public.tyre_shop_payments where advance_used<0 or payment_now<0 or amount<>advance_used+payment_now or remaining_payable<0 or remaining_advance<0) then 'PASS' else 'FAIL' end,'Payment/advance snapshots remain non-negative and balanced',true),
 ('PAYMENT_CASHBOOK_MATCH',case when not exists(select 1 from public.tyre_shop_payments p left join public.cashbook_entries c on c.reference_type='tyre_shop_payment' and c.reference_id=p.id::text where (p.payment_now>0 and (c.reference_id is null or c.amount<>p.payment_now or c.entry_type<>'Cash Out')) or (p.payment_now=0 and c.reference_id is not null)) then 'PASS' else 'FAIL' end,'Only payment_now has one matching Cash Out',true),
 ('NO_DUPLICATE_PAYMENT_CASHBOOK',case when not exists(select 1 from public.cashbook_entries where reference_type='tyre_shop_payment' group by reference_id having count(*)>1) then 'PASS' else 'FAIL' end,'No duplicate Tyre Shop payment references',true),
 ('VOUCHER_LINK_TABLE',case when to_regclass('public.voucher_tyre_entries') is not null then 'PASS' else 'FAIL' end,'Voucher-Tyre reference table exists',true),
 ('VOUCHER_LINK_RLS',case when coalesce((select relrowsecurity from pg_class where oid=to_regclass('public.voucher_tyre_entries')),false) and not has_table_privilege('authenticated','public.voucher_tyre_entries','INSERT') and has_table_privilege('authenticated','public.voucher_tyre_entries','SELECT') then 'PASS' else 'FAIL' end,'Voucher link is RLS protected, read-only to authenticated browser clients',true),
 ('SOURCE_AND_LINK_TRIGGERS',case when exists(select 1 from pg_trigger where tgrelid=to_regclass('public.tyre_vehicle_entries') and tgname='tyre_vehicle_entries_shop_bill' and not tgisinternal) and exists(select 1 from pg_trigger where tgrelid=to_regclass('public.voucher_tyre_entries') and tgname='voucher_tyre_entries_sync_cashbook' and not tgisinternal) then 'PASS' else 'FAIL' end,'Source liability sync and Voucher recalculation triggers exist',true),
 ('VOUCHER_LINK_UNIQUENESS',case when not exists(select 1 from public.voucher_tyre_entries group by tyre_vehicle_entry_id having count(*)>1) then 'PASS' else 'FAIL' end,'One Voucher maximum per Tyre entry',true),
 ('VOUCHER_LINK_CONTEXT',case when not exists(select 1 from public.voucher_tyre_entries link left join public.expenses e on e.id=link.voucher_id left join public.loadings l on l.id=e.loading_id left join public.bookings b on b.id=l.booking_id left join public.vehicles v on v.id=l.vehicle_id left join public.tyre_vehicle_entries t on t.id=link.tyre_vehicle_entry_id where e.id is null or l.id is null or v.id is null or t.id is null or t.vehicle_id<>l.vehicle_id or t.adda_id<>case when l.booking_id is null then v.adda_id else b.adda_id end) then 'PASS' else 'FAIL' end,'Linked Tyre rows match Voucher vehicle/Adda including legacy fallback',true),
 ('VOUCHER_RPC_SECURITY',case when to_regprocedure('public.sync_voucher_tyre_entries(bigint,uuid[])') is not null and exists(select 1 from pg_proc where oid=to_regprocedure('public.sync_voucher_tyre_entries(bigint,uuid[])') and prosecdef and array_to_string(proconfig,',') ilike '%search_path=%') and has_function_privilege('authenticated','public.sync_voucher_tyre_entries(bigint,uuid[])','EXECUTE') and not has_function_privilege('anon','public.sync_voucher_tyre_entries(bigint,uuid[])','EXECUTE') then 'PASS' else 'FAIL' end,'Validated authenticated-only Voucher sync RPC',true),
 ('VOUCHER_DELETE_LINK_ONLY',case when exists(select 1 from pg_constraint where conrelid=to_regclass('public.voucher_tyre_entries') and confrelid=to_regclass('public.expenses') and confdeltype='c') and exists(select 1 from pg_constraint where conrelid=to_regclass('public.voucher_tyre_entries') and confrelid=to_regclass('public.tyre_vehicle_entries') and confdeltype='r') then 'PASS' else 'FAIL' end,'Voucher cascades link only; Tyre source is restricted/preserved',true),
 ('VOUCHER_CASHBOOK_EXCLUSIONS',case when pg_get_functiondef(to_regprocedure('public.ut_sync_voucher_cashbook(text)')) ilike '%voucher_workshop_entries%' and pg_get_functiondef(to_regprocedure('public.ut_sync_voucher_cashbook(text)')) ilike '%voucher_oil_entries%' and pg_get_functiondef(to_regprocedure('public.ut_sync_voucher_cashbook(text)')) ilike '%voucher_tyre_entries%' then 'PASS' else 'FAIL' end,'Workshop, Oil and Tyre reference expenses excluded from Voucher Cash Out',true),
 ('NO_LINK_CASHBOOK_ROWS',case when not exists(select 1 from public.cashbook_entries where reference_type in('voucher_tyre_entry','tyre_vehicle_entry','tyre_shop_bill')) then 'PASS' else 'FAIL' end,'Link/source/bill creates no Cashbook transaction',true),
 ('COUNTS','INFO',format('%s bills; %s payments; %s allocations; %s Voucher links; %s Tyre payment Cashbook rows',(select count(*) from public.tyre_shop_bills),(select count(*) from public.tyre_shop_payments),(select count(*) from public.tyre_shop_payment_allocations),(select count(*) from public.voucher_tyre_entries),(select count(*) from public.cashbook_entries where reference_type='tyre_shop_payment')),false)
), combined as (
 select 'OVERALL_TYRE_ACCOUNTING_VOUCHER_POST_VERIFY'::text check_name,case when count(*) filter(where blocking and status='FAIL')=0 then 'PASS' else 'FAIL' end status,format('%s blocking check(s) failed; %s passed; %s informational',count(*) filter(where blocking and status='FAIL'),count(*) filter(where status='PASS'),count(*) filter(where status='INFO')) details from checks
 union all select check_name,status,details from checks
)
select check_name,status,details from combined order by case when check_name='OVERALL_TYRE_ACCOUNTING_VOUCHER_POST_VERIFY' then 0 else 1 end,check_name;
